def check_distinct(tup):
    try:
        return len(tup) == len(set(tup))
    except TypeError:
        seen = []
        for item in tup:
            if any(item == prev for prev in seen):
                return False
            seen.append(item)
        return True

def first_Digit(num):
    s = str(num).strip()
    if s.startswith("-"):
        s = s[1:]
    return int(s[0])

def find_Odd_Pair(arr, n):
    odd_count = 0
    even_count = 0

    for num in arr[:n]:
        if num % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    return odd_count * even_count

def unique_product(numbers):
    product = 1
    for number in set(numbers):
        product *= number
    return product

def is_Sub_Array(arr, sub):
    n = len(arr)
    m = len(sub)

    if m == 0:
        return True
    if m > n:
        return False

    for i in range(n - m + 1):
        if arr[i:i + m] == sub:
            return True

    return False

def last_Digit_Factorial(n):
    if n >= 5:
        return 0
    return [1, 1, 2, 6, 4][n]

def differ_At_One_Bit_Pos(a, b):
    xor = a ^ b
    return xor > 0 and (xor & (xor - 1)) == 0

def move_num(s):
    non_digits = []
    digits = []

    for ch in s:
        if '0' <= ch <= '9':
            digits.append(ch)
        else:
            non_digits.append(ch)

    return ''.join(non_digits + digits)

def get_median(arr1, arr2, n):
    if n <= 0:
        raise ValueError("n must be positive")

    i = j = 0
    previous = current = 0

    for _ in range(n + 1):
        previous = current

        if i == n:
            current = arr2[j]
            j += 1
        elif j == n:
            current = arr1[i]
            i += 1
        elif arr1[i] <= arr2[j]:
            current = arr1[i]
            i += 1
        else:
            current = arr2[j]
            j += 1

    return (previous + current) / 2.0

def max_difference(tuple_list):
    if not tuple_list:
        return 0
    return max(abs(a - b) for a, b in tuple_list)

def find_first_occurrence(arr, target):
    left, right = 0, len(arr) - 1
    result = -1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            result = mid
            right = mid - 1
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return result

def find_combinations(tuple_list):
    result = []
    for i in range(len(tuple_list)):
        for j in range(i + 1, len(tuple_list)):
            result.append(tuple(a + b for a, b in zip(tuple_list[i], tuple_list[j])))
    return result

def _sum(arr):
    total = 0
    for num in arr:
        total += num
    return total

def find_Rotations(s):
    n = len(s)
    if n == 0:
        return 0
    return (s + s).find(s, 1)
